sysevent_script_action.script:
try {
    //parm1 = array of fund details such as client, fund family, department, sla, statment date
    //parm2 = subject of initial email communication sent
    var eventArray = event.parm1.split(','); // MSSFUNDS-4: Get fund related details
	var faMakerGroup = gs.getProperty('x_hsb11_mss_fund_0.FA_Ops_Maker_Group');// SysID of FA Ops Maker Group
    var grTask = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
    grTask.addEncodedQuery("fund_name.fund_family=" + eventArray[1].trim() + "^department=" + eventArray[2].trim() + "^state=1");
    grTask.query(); // MSSFUNDS-4: Check applicable tasks
    while (grTask.next()) {
        grTask.assignment_group = faMakerGroup; // MSSFUNDS-4: Reassign to FA OPs Maker when no response
        grTask.comments = "No Response From Upstream/Corporate Action Team, Reassigning to FA Ops";
        grTask.update();

    }
} catch (e) {
    gs.info("Unknown Exception While Reassigning Tasks to FA Ops when no response" + e);
}
